import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Base premiums: simplest cases ---
  it.todo("empty item list → premium 5 G (only the processing fee)");
  it.todo("a sword → base premium 100 G, premium 115 G (100 + 10 first insurance + 5 fee)");
  it.todo("an amulet → base premium 60 G");
  it.todo("a staff → base premium 80 G");
  it.todo("a potion → base premium 40 G");
  it.todo("a single rune → base premium 25 G");
  it.todo("a single moonstone → base premium 25 G");

  // --- Building block of 3 alike components ---
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");

  // --- "Alike" components (❓ same type, not same family) ---
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("cursed sword adds 50 % of its base premium (100 → 150)");
  it.todo("sword with enchantment 5 adds 30 % high-enchantment surcharge (100 → 130)");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 → both surcharges apply (100 + 50 + 30)");

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first insurance carries a 10 % initial assessment surcharge per item");
  it.todo("second contract in a scenario receives a 15 % follow-up discount");

  // --- ❓ Modifier scope on multi-item policies ---
  it.todo(
    "cursed sword (100 G) + plain amulet (60 G) → base 160 G, curse adds 50 G (item scope) → 210 G before further modifiers and fee",
  );

  // --- Rounding in MHPCO's favor ---
  it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");

  // --- Integration examples ---
  it.todo("newcomer (0 years) with a cursed sword → premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed sword enchantment 7 → premium 160 G");

  // --- Claim processing: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G (no special clause)");

  // --- Claim processing: special clauses ---
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Deductible per damage event ---
  it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)");

  // --- ❓ Multiple items of the same type ---
  it.todo("a policy covers two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("two sword damage entries on a two-sword policy → each is a separate damage with its own deductible");
  it.todo("more damage entries of a type than the policy covers → CLI exits non-zero");

  // --- Cap ---
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a cursed sword (premium 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block affects premium only)");
  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword policy, second successive claim of 1500 G → payout 600 G, remainingCap 0 G");

  // --- Error cases ---
  it.todo("quote with an unknown item type (broomstick) → CLI exits non-zero with error on stderr, no results on stdout");
  it.todo("claim damaging an item not part of the policy (amulet when only a sword is insured) → CLI exits non-zero");
  it.todo("claim with a damage entry of an unknown item type → CLI exits non-zero");
  it.todo("claim with a damage entry amount -200 → CLI exits non-zero");

  // --- CLI end-to-end ---
  it.todo("CLI reads the schema example scenario from stdin and writes results to stdout");
});

