  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Deductible per damage event ---
  it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)");

  // --- ❓ Multiple items of the same type ---
  it.todo("a policy covers two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("two sword damage entries on a two-sword policy → each is a separate damage with its own deductible");
  it.todo("more damage entries of a type than the policy covers → CLI exits non-zero");

  // --- Cap ---
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a cursed sword (premium 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block affects premium only)");
  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword policy, second successive claim of 1500 G → payout 600 G, remainingCap 0 G");

  // --- Error cases ---
