const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

// Intermediate amounts are kept as fractions; only the final figure is rounded.
// Binary floating point makes sums like 100 * 1.1 + 5 land on 115.00000000000001,
// so that noise is trimmed before rounding.
const withoutFloatingPointNoise = (amount: number): number =>
  Number(amount.toPrecision(12));

// Rounding always favours MHPCO, which means up for what the customer pays.
const roundPremiumInMHPCOsFavor = (amount: number): number =>
  Math.ceil(withoutFloatingPointNoise(amount));

const basePremiumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const increasedBy = (amount: number, rate: number): number =>
  amount * (1 + rate);

const withFirstInsuranceSurcharge = (base: number): number =>
  increasedBy(base, FIRST_INSURANCE_SURCHARGE);

const withProcessingFee = (amount: number): number => amount + PROCESSING_FEE;

const premiumFor = (items: Item[]): number => {
  const base = basePremiumOf(items);
  const afterSurcharges = withFirstInsuranceSurcharge(base);
  return roundPremiumInMHPCOsFavor(withProcessingFee(afterSurcharges));
};

const quoteFor = (step: QuoteStep): QuoteResult => ({
  premium: premiumFor(step.items),
});

const resultOf = (step: Step): Result => {
  if (step.op === "quote") return quoteFor(step);
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map(resultOf),
});

