p='src/claim-office.ts'
s=open(p).read()

s=s.replace('''const withProcessingFee = (amount: number): number => amount + PROCESSING_FEE;''','''const withProcessingFee = (amount: number): number => amount + PROCESSING_FEE;

const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE = 100;
const CAP_MULTIPLE = 2;

// A policy created by a quote step: the items it covers and how much of its
// payout cap is still available.
interface Policy {
  items: Item[];
  remainingCap: number;
}

const insuranceSumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

// Rounding always favours MHPCO, which means down for what MHPCO pays out.
const roundPayoutInMHPCOsFavor = (amount: number): number =>
  Math.floor(withoutFloatingPointNoise(amount));

const payoutForDamage = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const claimFor = (step: ClaimStep, policies: Policy[]): ClaimResult => {
  const policy = policies[step.policy];
  const payout = roundPayoutInMHPCOsFavor(
    step.incident.damages.reduce(
      (sum, damage) => sum + payoutForDamage(damage),
      0,
    ),
  );
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};''',1)

s=s.replace('''export const runScenario = (scenario: Scenario): ScenarioResults => {
  const results: Result[] = [];
  let contractsIssued = 0;
  for (const step of scenario.steps) {
    if (step.op !== "quote") throw new Error(`Unsupported step: ${step.op}`);
    results.push(
      quoteFor(step, {
        customer: scenario.customer,
        previousContracts: contractsIssued,
      }),
    );
    contractsIssued += 1;
  }
  return { results };
};''','''export const runScenario = (scenario: Scenario): ScenarioResults => {
  const results: Result[] = [];
  const policies: Policy[] = [];
  let contractsIssued = 0;
  for (const step of scenario.steps) {
    if (step.op === "quote") {
      results.push(
        quoteFor(step, {
          customer: scenario.customer,
          previousContracts: contractsIssued,
        }),
      );
      policies[results.length - 1] = {
        items: step.items,
        remainingCap: CAP_MULTIPLE * insuranceSumOf(step.items),
      };
      contractsIssued += 1;
    } else {
      results.push(claimFor(step, policies));
    }
  }
  return { results };
};''',1)
