p='src/claim-office.ts'
s=open(p).read()
s=s.replace('''// A clause reduces the damage amount first; the deductible is withheld
// afterwards, once per damaged item.
const payoutForDamage = (damage: Damage, policy: Policy): number => {
  const item = policy.items.find(({ type }) => type === damage.itemType)!;
  return damage.amount * reimbursementRateFor(item) - DEDUCTIBLE;
};

const payoutForIncident = (incident: Incident, policy: Policy): number =>
  roundPayoutInMHPCOsFavor(
    incident.damages.reduce(
      (sum, damage) => sum + payoutForDamage(damage, policy),
      0,
    ),
  );''','''// A clause reduces the damage amount first; the deductible is withheld
// afterwards, once per damaged item.
const payoutForDamage = (damage: Damage, item: Item): number =>
  damage.amount * reimbursementRateFor(item) - DEDUCTIBLE;

// Every damage entry names a distinct covered item, so two entries of one type
// need two such items on the policy. A damage MHPCO cannot match to a covered
// item rejects the whole claim.
const damagedItemsOf = (incident: Incident, policy: Policy): Item[] => {
  const uncovered = [...policy.items];
  return incident.damages.map((damage) => {
    const index = uncovered.findIndex(({ type }) => type === damage.itemType);
    if (index === -1) {
      throw new Error(`Not covered by this policy: ${damage.itemType}`);
    }
    return uncovered.splice(index, 1)[0];
  });
};

const payoutForIncident = (incident: Incident, policy: Policy): number =>
  roundPayoutInMHPCOsFavor(
    damagedItemsOf(incident, policy).reduce(
      (sum, item, index) => sum + payoutForDamage(incident.damages[index], item),
      0,
    ),
  );''',1)
open(p,'w').write(s)
